<?php
declare(strict_types=1); require_once __DIR__.'/../auth/role_helper.php'; $allowedRoles=[ROLE_DISCIPLINARY_OFFICER]; require_once __DIR__.'/../auth/session_guard.php';
$pageTitle='Reports';$activePage='guidance_reports';$roleStylesheet='assets/css/teacher.css';$pageStylesheet='assets/css/pages/guidance.css';$userId=(int)$_SESSION['user_id'];
$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?(string)$_GET['from']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?(string)$_GET['to']:'';$referralStatus=in_array($_GET['referral_status']??'', ['','Submitted','Returned','Accepted','Closed'],true)?(string)($_GET['referral_status']??''):'';$caseStatus=in_array($_GET['case_status']??'', ['','Open','Active','Closed'],true)?(string)($_GET['case_status']??''):'';$followupStatus=in_array($_GET['followup_status']??'', ['','Scheduled','Completed','Cancelled'],true)?(string)($_GET['followup_status']??''):'';$studentSearch=trim((string)($_GET['student']??''));
$base=" FROM teacher_referrals tr INNER JOIN guidance_cases gc ON gc.teacher_referral_id=tr.teacher_referral_id INNER JOIN guidance_case_assignments gca ON gca.guidance_case_id=gc.guidance_case_id AND gca.assigned_user_id=? AND gca.ended_at IS NULL INNER JOIN students s ON s.student_id=tr.student_id";$where=[];$params=[$userId];if($from!==''){$where[]='tr.created_at >= ?';$params[]=$from.' 00:00:00';}if($to!==''){$where[]='tr.created_at < DATE_ADD(?,INTERVAL 1 DAY)';$params[]=$to.' 00:00:00';}if($referralStatus!==''){$where[]='tr.status=?';$params[]=$referralStatus;}if($caseStatus!==''){$where[]='gc.case_status=?';$params[]=$caseStatus;}if($studentSearch!==''){$where[]="CONCAT_WS(' ',s.first_name,s.last_name) LIKE ?";$params[]='%'.$studentSearch.'%';}if($followupStatus!==''){$where[]='EXISTS (SELECT 1 FROM guidance_followups f_filter WHERE f_filter.guidance_case_id=gc.guidance_case_id AND f_filter.assigned_user_id=? AND f_filter.followup_status=?)';$params[]=$userId;$params[]=$followupStatus;}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$run=static function(PDO $pdo,string $sql,array $params):array{$stmt=$pdo->prepare($sql);$stmt->execute($params);return $stmt->fetchAll(PDO::FETCH_ASSOC);};$countRows=static function(PDO $pdo,string $sql,array $params):int{$stmt=$pdo->prepare($sql);$stmt->execute($params);return(int)$stmt->fetchColumn();};
$referralRows=$run($pdo,"SELECT tr.status label,COUNT(DISTINCT tr.teacher_referral_id) total".$base.$whereSql." GROUP BY tr.status ORDER BY FIELD(tr.status,'Submitted','Returned','Accepted','Closed')",$params);$caseRows=$run($pdo,"SELECT gc.case_status label,COUNT(DISTINCT gc.guidance_case_id) total".$base.$whereSql." GROUP BY gc.case_status ORDER BY FIELD(gc.case_status,'Open','Active','Closed')",$params);
$followBase=" FROM guidance_followups f INNER JOIN guidance_cases gc ON gc.guidance_case_id=f.guidance_case_id INNER JOIN teacher_referrals tr ON tr.teacher_referral_id=gc.teacher_referral_id INNER JOIN guidance_case_assignments gca ON gca.guidance_case_id=gc.guidance_case_id AND gca.assigned_user_id=? AND gca.ended_at IS NULL INNER JOIN students s ON s.student_id=tr.student_id";$followWhere=[];$followParams=[$userId];if($from!==''){$followWhere[]='f.scheduled_at >= ?';$followParams[]=$from.' 00:00:00';}if($to!==''){$followWhere[]='f.scheduled_at < DATE_ADD(?,INTERVAL 1 DAY)';$followParams[]=$to.' 00:00:00';}if($referralStatus!==''){$followWhere[]='tr.status=?';$followParams[]=$referralStatus;}if($caseStatus!==''){$followWhere[]='gc.case_status=?';$followParams[]=$caseStatus;}if($studentSearch!==''){$followWhere[]="CONCAT_WS(' ',s.first_name,s.last_name) LIKE ?";$followParams[]='%'.$studentSearch.'%';}if($followupStatus!==''){$followWhere[]='f.followup_status=?';$followParams[]=$followupStatus;}$followWhereSql=$followWhere?' WHERE '.implode(' AND ',$followWhere):'';$followupRows=$run($pdo,"SELECT f.followup_status label,COUNT(*) total".$followBase.$followWhereSql." GROUP BY f.followup_status ORDER BY FIELD(f.followup_status,'Scheduled','Completed','Cancelled')",$followParams);
$trendRows=$run($pdo,"SELECT DATE_FORMAT(tr.created_at,'%b %Y') label,DATE_FORMAT(tr.created_at,'%Y-%m') sort_key,COUNT(DISTINCT tr.teacher_referral_id) total".$base.$whereSql." GROUP BY sort_key,label ORDER BY sort_key",$params);$resultRows=$run($pdo,"SELECT DISTINCT tr.teacher_referral_id,gc.guidance_case_id,gc.case_number,tr.status referral_status,gc.case_status,CONCAT_WS(' ',s.first_name,s.last_name) student_name,s.student_number,tr.created_at,gc.opened_at".$base.$whereSql." ORDER BY tr.created_at DESC LIMIT 100",$params);
$totalReferrals=$countRows($pdo,"SELECT COUNT(DISTINCT tr.teacher_referral_id)".$base.$whereSql,$params);$totalCases=$countRows($pdo,"SELECT COUNT(DISTINCT gc.guidance_case_id)".$base.$whereSql,$params);$totalFollowups=$countRows($pdo,'SELECT COUNT(*)'.$followBase.$followWhereSql,$followParams);$overdueWhere=$followWhere;$overdueParams=$followParams;$overdueWhere[]="f.followup_status='Scheduled'";$overdueWhere[]='f.scheduled_at<NOW()';$overdueWhereSql=' WHERE '.implode(' AND ',$overdueWhere);$overdue=$countRows($pdo,'SELECT COUNT(*)'.$followBase.$overdueWhereSql,$overdueParams);
$chartJson=static fn(array $values):string=>htmlspecialchars(json_encode(array_values($values),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT),ENT_QUOTES,'UTF-8');$normalize=static function(array $rows,array $labels):array{$counts=[];foreach($rows as $row)$counts[(string)$row['label']]=(int)$row['total'];return array_map(static fn(string $label):array=>['label'=>$label,'total'=>$counts[$label]??0],$labels);};$referralRows=$normalize($referralRows,['Submitted','Returned','Accepted','Closed']);$caseRows=$normalize($caseRows,['Open','Active','Closed']);$followupRows=$normalize($followupRows,['Scheduled','Completed','Cancelled']);function guidanceReportEsc(?string $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><?php require __DIR__.'/../includes/components/head.php';?><body><?php require __DIR__.'/../includes/components/sidebar.php';?><main class="main-content"><div class="main-wrapper"><?php require __DIR__.'/../includes/components/top-navbar.php';?><section class="guidance-page guidance-report-page"><header class="guidance-page-header"><div><p class="page-eyebrow">Disciplinary Officer</p><h1>Reports</h1><p class="guidance-context-meta">Assigned operational records</p></div></header><div class="guidance-report-layout"><aside class="guidance-panel guidance-report-filters"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Scope</p><h2>Report filters</h2></div><a class="guidance-text-link" href="<?=APP_URL?>/dashboard/guidance_reports.php">Reset</a></div><form method="get" class="guidance-report-filter-form"><label>Date from<input type="date" name="from" value="<?=guidanceReportEsc($from)?>"></label><label>Date to<input type="date" name="to" value="<?=guidanceReportEsc($to)?>"></label><label>Student<input type="search" name="student" placeholder="Student name" value="<?=guidanceReportEsc($studentSearch)?>"></label><label>Referral status<select name="referral_status"><option value="">All statuses</option><?php foreach(['Submitted','Returned','Accepted','Closed'] as $option):?><option value="<?=$option?>" <?=$referralStatus===$option?'selected':''?>><?=$option?></option><?php endforeach;?></select></label><label>Case status<select name="case_status"><option value="">All statuses</option><?php foreach(['Open','Active','Closed'] as $option):?><option value="<?=$option?>" <?=$caseStatus===$option?'selected':''?>><?=$option?></option><?php endforeach;?></select></label><label>Follow-up status<select name="followup_status"><option value="">All statuses</option><?php foreach(['Scheduled','Completed','Cancelled'] as $option):?><option value="<?=$option?>" <?=$followupStatus===$option?'selected':''?>><?=$option?></option><?php endforeach;?></select></label><button class="btn btn-primary" type="submit">Apply filters</button></form></aside><main class="guidance-report-main"><section class="guidance-report-summary" aria-label="Filtered record summary">
    <article class="guidance-report-kpi">
        <span class="guidance-report-kpi-icon"><i data-lucide="file-text" aria-hidden="true"></i></span>
        <span class="guidance-report-kpi-label">Referrals</span>
        <strong><?=$totalReferrals?></strong>
    </article>
    <article class="guidance-report-kpi">
        <span class="guidance-report-kpi-icon"><i data-lucide="folder-open" aria-hidden="true"></i></span>
        <span class="guidance-report-kpi-label">Cases</span>
        <strong><?=$totalCases?></strong>
    </article>
    <article class="guidance-report-kpi">
        <span class="guidance-report-kpi-icon"><i data-lucide="calendar-clock" aria-hidden="true"></i></span>
        <span class="guidance-report-kpi-label">Follow-ups</span>
        <strong><?=$totalFollowups?></strong>
    </article>
    <article class="guidance-report-kpi<?= $overdue > 0 ? ' is-alert' : '' ?>">
        <span class="guidance-report-kpi-icon"><i data-lucide="clock-3" aria-hidden="true"></i></span>
        <span class="guidance-report-kpi-label">Overdue</span>
        <strong><?=$overdue?></strong>
    </article>
</section><div class="guidance-report-analytics"><section class="guidance-report-status-grid" aria-label="Filtered status distributions"><?php foreach([['Referral Status',$referralRows],['Case Status',$caseRows],['Follow-up Status',$followupRows]] as [$statusTitle,$statusRows]):$statusTotal=array_sum(array_map(static fn(array $row):int=>(int)$row['total'],$statusRows));?><article class="guidance-panel guidance-report-status-card"><div class="guidance-report-status-heading"><h2><?=guidanceReportEsc($statusTitle)?></h2><span>Total <strong><?=$statusTotal?></strong></span></div><div class="guidance-report-status-bar" aria-hidden="true"><?php foreach($statusRows as $statusRow):$statusCount=(int)$statusRow['total'];if($statusCount===0)continue;$statusKey=strtolower((string)$statusRow['label']);?><span class="guidance-report-status-segment" data-status="<?=guidanceReportEsc($statusKey)?>" style="flex-grow:<?=$statusCount?>"></span><?php endforeach;?></div><ul class="guidance-report-status-list" aria-label="<?=guidanceReportEsc($statusTitle)?> breakdown"><?php foreach($statusRows as $statusRow):$statusCount=(int)$statusRow['total'];$statusPercent=$statusTotal>0?(int)round(($statusCount/$statusTotal)*100):0;$statusKey=strtolower((string)$statusRow['label']);?><li class="guidance-report-status-row" data-status="<?=guidanceReportEsc($statusKey)?>"><span class="guidance-report-status-marker" aria-hidden="true"></span><span class="guidance-report-status-label"><?=guidanceReportEsc($statusRow['label'])?></span><span class="guidance-report-status-count"><?=$statusCount?></span><span class="guidance-report-status-percent"><?=$statusPercent?>%</span></li><?php endforeach;?></ul></article><?php endforeach;?></section><article class="guidance-panel guidance-chart-panel guidance-report-trend-panel"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Submitted over time</p><h2>Referral trend</h2></div></div><?php if(array_sum(array_map(static fn(array $row):int=>(int)$row['total'],$trendRows))===0):?><div class="guidance-empty-state is-compact">No referral trend data.</div><?php else:?><div class="guidance-chart-wrap"><canvas data-aprism-chart data-chart-type="line" data-chart-labels="<?=$chartJson(array_column($trendRows,'label'))?>" data-chart-values="<?=$chartJson(array_column($trendRows,'total'))?>" aria-label="Referral trend chart"></canvas></div><?php endif;?></article></div><section class="guidance-panel guidance-report-results"><div class="guidance-panel-heading"><div><p class="guidance-section-kicker">Records</p><h2>Filtered results</h2></div><span class="guidance-toolbar-meta"><?=count($resultRows)?> shown</span></div><div class="guidance-table-wrap"><table class="guidance-table"><thead><tr><th>Case</th><th>Student</th><th>Referral</th><th>Case status</th><th>Submitted</th><th>Action</th></tr></thead><tbody><?php foreach($resultRows as $row):?><tr><td data-label="Case"><?=guidanceReportEsc($row['case_number'])?></td><td data-label="Student"><strong><?=guidanceReportEsc($row['student_name'])?></strong><small><?=guidanceReportEsc((string)$row['student_number'])?></small></td><td data-label="Referral"><span class="guidance-status <?=strtolower((string)$row['referral_status'])?>"><?=guidanceReportEsc($row['referral_status'])?></span></td><td data-label="Case status"><span class="guidance-status <?=strtolower((string)$row['case_status'])?>"><?=guidanceReportEsc($row['case_status'])?></span></td><td data-label="Submitted"><?=guidanceReportEsc($row['created_at'])?></td><td data-label="Action"><a class="btn btn-secondary" href="<?=APP_URL?>/dashboard/guidance_case.php?case_id=<?=(int)$row['guidance_case_id']?>">Open case</a></td></tr><?php endforeach;?><?php if($resultRows===[]):?><tr><td colspan="6" class="guidance-empty">No records match the selected scope.</td></tr><?php endif;?></tbody></table></div></section><p class="guidance-report-note">Counts reflect assigned records only. Confidential notes are excluded.</p></main></div></section></div></main><?php require __DIR__.'/../includes/components/footer.php';?></body></html>
